SELECT  FROM t_connector_item
WHERE connector_id=#{connectorId}

ORDER BY COALESCE(remote_updated_at, synced_time) DESC, id DESC
LIMIT #{offset},#{size}

SELECT attributes_json FROM t_connector_item
WHERE connector_id=#{connectorId}
AND item_type = #{type}
ORDER BY id DESC LIMIT #{limit}

SELECT connector_item_id FROM t_connector_item_binding
WHERE connector_id=#{connectorId}
AND ingest_status=#{status}
ORDER BY connector_item_id

